import json,sys,itertools,numpy as np,scipy.linalg as sl
from collections import deque
def setup(coords,edges):
    de=[];
    for k,(a,b,J) in enumerate(edges): de.append((a,b,k)); de.append((b,a,k))
    out={}
    for idx,(u,v,k) in enumerate(de): out.setdefault(u,[]).append(idx)
    n=len(de); M=np.zeros((n,n),complex)
    t=np.tanh([e[2] for e in edges])
    for i,(u,v,k) in enumerate(de):
        d1=np.subtract(coords[v],coords[u]); a1=np.arctan2(d1[1],d1[0])
        for j in out[v]:
            _,w,k2=de[j]
            if w==u: continue
            d2=np.subtract(coords[w],coords[v]); al=np.arctan2(d2[1],d2[0])-a1
            al=(al+np.pi)%(2*np.pi)-np.pi
            M[i,j]=t[k2]*np.exp(1j*al/2)
    return de,M,t
def solve(coords,edges,lig,spins,rep):
    N=len(coords); de,M,t=setup(coords,edges); n=len(de)
    A=np.eye(n)-M; lu=sl.lu_factor(A)
    ld=np.sum(np.log(np.diag(lu[0]).astype(complex)))  # perm sign: ignore, check real
    logZ=N*np.log(2)+np.sum(np.log(np.cosh([e[2] for e in edges])))+0.5*ld.real
    adj={}
    for k,(a,b,J) in enumerate(edges): adj.setdefault(a,[]).append((b,k)); adj.setdefault(b,[]).append((a,k))
    sites=list(lig)+list(rep); root=sites[0]
    par={root:None}; q=deque([root])
    while q:
        x=q.popleft()
        for y,k in adj[x]:
            if y not in par: par[y]=(x,k); q.append(y)
    paths=[]
    for s in sites:
        p=set()
        while par[s]: x,k=par[s]; p^={k}; s=x
        paths.append(p)
    U=sorted(set().union(*paths)); Ud=[i for i,(u,v,k) in enumerate(de) if k in U]
    E=np.zeros((n,len(Ud)),complex); E[Ud,range(len(Ud))]=1
    G=sl.lu_solve(lu,E)[Ud,:]; K=G-np.eye(len(Ud))
    m=len(sites); corr={}
    for mask in range(1<<m):
        if bin(mask).count('1')%2: continue
        g=set()
        for i in range(m):
            if mask>>i&1: g^=paths[i]
        if not g: corr[mask]=1.0; continue
        r=np.array([ (1/t[de[i][2]]**2 -1) if de[i][2] in g else 0 for i in Ud])
        dr=np.linalg.det(np.eye(len(Ud))-K*r[None,:])
        corr[mask]=np.prod([t[k] for k in g])*np.sqrt(dr.real)
        assert abs(dr.imag)<1e-8*abs(dr)
    # note r: t'/t -1 with t'=1/t
    sig=list(spins)
    L=len(lig); full=np.zeros(1<<len(rep))
    for rm in range(1<<len(rep)):
        rs=[1-2*((rm>>(len(rep)-1-j))&1) for j in range(len(rep))]
        vals=sig+rs; tot=0
        for mask,c in corr.items():
            pr=1
            for i in range(m):
                if mask>>i&1: pr*=vals[i]
            tot+=pr*c
        full[rm]=tot/2**m
    pc=sum(c*np.prod([sig[i] for i in range(L) if mask>>i&1]) for mask,c in corr.items() if mask< (1<<L))/2**L
    return logZ,np.log(pc),full/full.sum(),full.sum()/pc
if __name__=='__main__':
    d=json.load(open(sys.argv[1]))
    lz,lp,P,chk=solve(d['coordinates'],d['edges'],d['ligand_sites'],d['ligand_spins'],d['reporter_sites'])
    print(lz,lp,chk,P.sum())
    open('/root/results/thermodynamics.csv','w').write(f"metric,value\nlog_partition,{lz:.12f}\nlog_clamp_probability,{lp:.12f}\n")
    with open('/root/results/reporter_distribution.csv','w') as f:
        f.write("pattern,probability\n")
        for i in range(256): f.write(f"{i:08b},{max(P[i],0):.15e}\n")
EOF
